const b = ($input.first() && $input.first().json && $input.first().json.body) || {};

if (b.amount && b.description) {
  return [{
    json: {
      source: "MANUAL",
      rawText: "",
      chatId: null,
      senderHint: null,
      receivedAt: new Date().toISOString(),
      amount: b.amount,
      description: b.description,
      date: b.date || null,
      type: b.type || "EXPENSE",
      currency: b.currency || "AED",
    },
  }];
}

return [{
  json: {
    source: "MANUAL",
    rawText: b.rawText || "",
    chatId: null,
    senderHint: null,
    receivedAt: new Date().toISOString(),
  },
}];
